/**
 * tests/quotationPdf.service.test.ts
 *
 * Tests for quotationPdf.service.ts. The PDF text is extracted from the
 * generated bytes (FlateDecode streams are inflated and Tj/TJ operands decoded),
 * so assertions check what is actually rendered, not just that bytes exist.
 *
 * LIMITATION: the data model is one Quote document per part (Quote.partId) and the
 * PDF service renders exactly one part per quote. Multi-part PDFs are therefore
 * NOT supported and the multi-part requirement is recorded as it.todo below.
 */

import { describe, it, expect } from 'vitest';
import zlib from 'zlib';
import mongoose from 'mongoose';
import { generateQuotationPdf } from '../src/services/quotationPdf.service';
import type { IQuote } from '../src/models/Quote';

const d128 = (s: string) => mongoose.Types.Decimal128.fromString(s);

/** Extract rendered text from a PDFKit buffer. */
function pdfText(buf: Buffer): string {
  const raw = buf.toString('latin1');
  const out: string[] = [];
  const re = /stream\r?\n([\s\S]*?)\r?\nendstream/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(raw))) {
    let content: string;
    try {
      content = zlib.inflateSync(Buffer.from(m[1], 'latin1')).toString('latin1');
    } catch {
      content = m[1];
    }
    for (const h of content.matchAll(/<([0-9a-fA-F]+)>/g)) {
      out.push(Buffer.from(h[1], 'hex').toString('latin1'));
    }
    for (const s of content.matchAll(/\(((?:\\.|[^\\)])*)\)\s*Tj/g)) out.push(s[1]);
    out.push('\n');
  }
  return out.join('');
}

function quote(overrides: Record<string, unknown> = {}): IQuote {
  return {
    _id: new mongoose.Types.ObjectId(),
    rfqId: new mongoose.Types.ObjectId(),
    version: 1,
    status: 'APPROVED',
    annualQuotationValue: '20043000.00',
    costingDate: new Date('2026-11-07'),
    rateSnapshot: {
      material: 'EN8',
      materialRatePerKg: d128('70.00'),
      materialRateEffectiveFrom: new Date('2024-07-01'),
      operations: [
        {
          operationName: 'Turning',
          machine: 'CNC Lathe',
          cycleTimeMinutes: d128('3.20'),
          machineHourRate: d128('850.00'),
          machineRateEffectiveFrom: new Date('2024-07-01'),
        },
      ],
      snapshotCreatedAt: new Date(),
    },
    costBreakdown: {
      materialCost: '42.70',
      scrapCost: '1.71',
      conversionCost: '45.33',
      overheadCost: '7.18',
      packingFreight: '2.50',
      setupAllocationPerPiece: '0.00',
      totalCost: '99.42',
      sellingPriceExGst: '111.35',
      gstAmount: '20.04',
      sellingPriceIncludingGst: '131.39',
    },
    volumeTierResults: [
      { tierName: 'Low', tierPercentage: 50, tierVolume: 90000, totalCostPerPiece: '99.42', sellingPriceExGst: '113.95', gstAmount: '20.51', sellingPriceIncludingGst: '134.46' },
      { tierName: 'Base', tierPercentage: 100, tierVolume: 180000, totalCostPerPiece: '99.42', sellingPriceExGst: '111.35', gstAmount: '20.04', sellingPriceIncludingGst: '131.39' },
      { tierName: 'High', tierPercentage: 150, tierVolume: 270000, totalCostPerPiece: '99.42', sellingPriceExGst: '109.52', gstAmount: '19.71', sellingPriceIncludingGst: '129.23' },
    ],
    ...overrides,
  } as unknown as IQuote;
}

const rfq = { rfqNo: 'RFQ-2611-014', customer: 'Company B' };

describe('generateQuotationPdf — single part, rendered content', () => {
  it('produces a valid PDF', async () => {
    const buf = await generateQuotationPdf(quote(), rfq);
    expect(buf.slice(0, 5).toString('ascii')).toBe('%PDF-');
  });

  it('renders RFQ number, customer and no invented customer fields', async () => {
    const t = pdfText(await generateQuotationPdf(quote(), rfq));
    expect(t).toContain('RFQ-2611-014');
    expect(t).toContain('Company B');
  });

  it('renders all three volume tiers from the snapshot', async () => {
    const t = pdfText(await generateQuotationPdf(quote(), rfq));
    for (const v of ['Low', 'Base', 'High', '113.95', '111.35', '109.52']) {
      expect(t).toContain(v);
    }
  });

  it('shows the cost breakdown and GST separately from ex-GST price', async () => {
    const t = pdfText(await generateQuotationPdf(quote(), rfq));
    for (const v of ['42.70', '1.71', '45.33', '7.18', '2.50', '99.42', '111.35', '20.04', '131.39']) {
      expect(t).toContain(v);
    }
    expect(t).toContain('GST Amount');
    expect(t).toContain('Ex-GST');
  });

  it('shows the persisted annual quotation value verbatim', async () => {
    const t = pdfText(await generateQuotationPdf(quote(), rfq));
    expect(t).toContain('2,00,43,000.00');
  });

  it('uses snapshot values only: changing nothing but the snapshot changes the PDF', async () => {
    const t = pdfText(
      await generateQuotationPdf(
        quote({ costBreakdown: { ...quote().costBreakdown, materialCost: '55.55' } }),
        rfq,
      ),
    );
    expect(t).toContain('55.55');
    expect(t).not.toContain('42.70');
  });

  it('renders for READY_FOR_SALES quotes', async () => {
    const buf = await generateQuotationPdf(quote({ status: 'READY_FOR_SALES' }), rfq);
    expect(buf.slice(0, 5).toString('ascii')).toBe('%PDF-');
  });

  it.todo(
    'multi-part PDF: both parts, per-part breakdown/tiers, combined annual value — NOT SUPPORTED: one Quote per part, service renders one part',
  );
});
